SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.NAME AS oblname, Имена_станций.ordnumb, Станции2012.YEAR, Станции2012.NUST, Станции2012.nr, Станции2012.E, Станции2012.EOTP, Станции2012.EURT, Станции2012.EUST, Станции2012.Q, Станции2012.TURT, Станции2012.TUST, Станции2012.B, Станции2012.GAZ, Доп_угли2012.gazpp, Станции2012.MAZUT, Станции2012.TORF, Станции2012.SLAN, Станции2012.PROCH, Станции2012.UGOL, Станции2012.DON, Станции2012.PODM, Станции2012.PECH, Доп_угли2012.intin, Доп_угли2012.vork, Станции2012.ARKT, Станции2012.KUZN, Доп_угли2012.kuzngd, Доп_угли2012.kuznt, Доп_угли2012.kuznss, Доп_угли2012.kuznun, Станции2012.URAL, Доп_угли2012.sver, Доп_угли2012.chel, Доп_угли2012.kizel, Станции2012.BASHK, Станции2012.KAZAH, Доп_угли2012.ekib, Доп_угли2012.maikub, Станции2012.KARAG, Станции2012.KAN, Доп_угли2012.nazar, Доп_угли2012.ibor, Доп_угли2012.berez, Доп_угли2012.per, Доп_угли2012.irbei, Доп_угли2012.kansk, Станции2012.TUNG, Доп_угли2012.jer, Доп_угли2012.karab, Станции2012.IRKUT, Доп_угли2012.azey, Доп_угли2012.mug, Доп_угли2012.cher, Станции2012.HAK, Станции2012.TUV, Станции2012.BUR, Доп_угли2012.gusin, Доп_угли2012.tugn, Доп_угли2012.okino, Станции2012.CHIT, Доп_угли2012.har, Доп_угли2012.urt, Доп_угли2012.tataur, Доп_угли2012.tarbag, Доп_угли2012.zab_kam, Станции2012.YAKUT, Доп_угли2012.neru, Доп_угли2012.zyryan, Доп_угли2012.pyak, Станции2012.AMUR, Доп_угли2012.rai, Доп_угли2012.erk, Станции2012.URG, Станции2012.USHUM, Станции2012.PRIM, Доп_угли2012.bikin, Доп_угли2012.razdol, Доп_угли2012.hankai, Станции2012.MAG, Станции2012.SAH, Станции2012.KAMCH, Станции2012.CHUKOT, Доп_угли2012.anad, Доп_угли2012.bering, Станции2012.QOTR, Станции2012.SNK, Станции2012.EWTP, Станции2012.NT, Станции2012.OBOR, Станции2012.VED, Станции2012.OBL, Станции2012.DEP, Станции2012.OES, Станции2012.ER, Станции2012.NUMB1120, Имена_станций.Ведомство AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Имена_станций.FO, Имена_станций.форэм, Имена_станций.GK, Станции2012.BE, имена_ГК.name AS namegk, имена_БЕ.name AS namebe, Города.Name AS Town, IIf([obor]=20 Or [obor]=90,"ГТУ",IIf([obor]=21 Or [obor]=91,"ПГУ",IIf([obor]=22,"Диз",IIf([obor]=23,"Дет","ПСУ")))) AS тип
FROM (((Имена_станций LEFT JOIN Города ON Имена_станций.codegor=Города.code) INNER JOIN (Имена_областей INNER JOIN (Имена_ОЭС INNER JOIN (Станции2012 LEFT JOIN Доп_угли2012 ON (Станции2012.NUMB1120=Доп_угли2012.NUMB1120) AND (Станции2012.YEAR=Доп_угли2012.YEAR)) ON Имена_ОЭС.oes=Станции2012.OES) ON Имена_областей.OBL=Станции2012.OBL) ON Имена_станций.NUMB=Станции2012.NUMB1120) LEFT JOIN имена_ГК ON Станции2012.GK=имена_ГК.code) LEFT JOIN имена_БЕ ON Станции2012.BE=имена_БЕ.code;
